import unittest
from semver import Version, match_range

class TestSemVer(unittest.TestCase):
    def test_caret_and_tilde(self):
        self.assertTrue(match_range('1.4.0', '^1.2.3'))
        self.assertFalse(match_range('2.0.0', '^1.2.3'))
        self.assertTrue(match_range('1.2.9', '~1.2.3'))
        self.assertFalse(match_range('1.3.0', '~1.2.3'))

if __name__ == '__main__': unittest.main()

